import { jsx } from 'react/jsx-runtime';
import { useRef, useContext, useLayoutEffect } from 'react';
import { TransitionGroupContext } from '../TransitionGroup/TransitionGroupContext.js';
import { setStyle, removeStyle } from '../../utils/index.js';

const CSSTransition = ({ children, as, initial, animate, exit, duration, easing = 'ease', style, ...props }) => {
    const Component = as || 'div';
    const elementRef = useRef(null);
    const context = useContext(TransitionGroupContext);
    if (context === undefined) {
        throw new Error('CSSTransition must be used within an TransitionGroup');
    }
    const { isUnmounted, key, requestUnmount } = context;
    useLayoutEffect(() => {
        const element = elementRef.current;
        if (!element) {
            return;
        }
        element.style.transition = `all ${duration}ms ${easing}`;
        void element.offsetTop;
        setStyle(element, initial);
        void element.offsetTop;
        removeStyle(element, initial);
        setStyle(element, animate);
        // eslint-disable-next-line
    }, []);
    useLayoutEffect(() => {
        const element = elementRef.current;
        if (!isUnmounted || !element) {
            return;
        }
        const handleTransitionEnd = (e) => {
            const element = elementRef.current;
            if (!element || e.target !== element) {
                return;
            }
            requestUnmount(key);
        };
        element.addEventListener('transitionend', handleTransitionEnd);
        removeStyle(element, initial);
        removeStyle(element, animate);
        element.style.pointerEvents = 'none';
        setStyle(element, exit);
        return () => {
            element.removeEventListener('transitionend', handleTransitionEnd);
        };
        // eslint-disable-next-line
    }, [isUnmounted, key, requestUnmount]);
    return (jsx(Component, { ref: elementRef, style: { ...initial, ...style }, ...props, children: children }));
};

export { CSSTransition };
