import { jsx } from 'react/jsx-runtime';
import 'react';
import { TransitionGroupContext } from './TransitionGroupContext.js';

const TransitionChild = ({ children, id, elementKey, isUnmounted, onRequestUnmount, }) => {
    return (jsx(TransitionGroupContext.Provider, { value: { isUnmounted, key: elementKey, requestUnmount: onRequestUnmount }, children: children }, `${elementKey}-${id}`));
};

export { TransitionChild };
