"use client";
import { jsx } from 'react/jsx-runtime';
import { useContext, useEffect } from 'react';
import { SelectContext } from './SelectContext.js';
import { selectOption } from './SelectOption.css.vanilla.js';

const SelectOption = ({ children, value }) => {
    const selectContext = useContext(SelectContext);
    if (!selectContext) {
        throw new Error('SelectOption must be rendered within a Select.');
    }
    const { dispatch } = selectContext;
    useEffect(() => {
        dispatch({ type: 'ADD', payload: { value, children } });
        return () => {
            dispatch({ type: 'REMOVE', payload: { value } });
        };
        // eslint-disable-next-line
    }, [dispatch, value]);
    const handleClick = () => {
        dispatch({ type: 'SELECT', payload: { value } });
    };
    return (jsx("div", { className: selectOption, onClick: handleClick, children: children }));
};

export { SelectOption };
