import { jsx } from 'react/jsx-runtime';
import { useRef, useContext, useEffect } from 'react';
import { OverlayContext } from './OverlayContext.js';

const Overlay = ({ children, id, isActive, className, closeOnBackdropClick, unmountOn, requestUnmount, }) => {
    const wrapperRef = useRef(null);
    const timerRef = useRef(undefined);
    const overlayContext = useContext(OverlayContext);
    if (!overlayContext) {
        throw new Error('Overlay must be used within an OverlayContext.');
    }
    useEffect(() => {
        if (!wrapperRef.current) {
            return;
        }
        if (isActive) {
            if (className?.base) {
                wrapperRef.current.classList.add(className.base);
            }
            if (className?.enter) {
                // eslint-disable-next-line
                wrapperRef.current.offsetTop;
                wrapperRef.current.classList.add(className.enter);
            }
            return;
        }
        switch (unmountOn) {
            case 'exit': {
                if (requestUnmount) {
                    requestUnmount();
                }
                break;
            }
            case 'transitionEnd': {
                if (className?.exit) {
                    wrapperRef.current.classList.add(className.exit);
                }
                break;
            }
            default: {
                timerRef.current = setTimeout(() => {
                    if (requestUnmount) {
                        requestUnmount();
                    }
                }, Number(unmountOn));
            }
        }
    }, [
        wrapperRef,
        isActive,
        className?.base,
        className?.enter,
        className?.exit,
        unmountOn,
        requestUnmount,
    ]);
    const handleTransitionEnd = (e) => {
        if (e.target !== wrapperRef.current ||
            isActive ||
            unmountOn !== 'transitionEnd' ||
            !requestUnmount) {
            return;
        }
        requestUnmount();
    };
    const handleClick = (e) => {
        if (e.target !== wrapperRef.current || !isActive || !closeOnBackdropClick) {
            return;
        }
        overlayContext.close(id);
    };
    return (jsx("div", { ref: wrapperRef, onClick: handleClick, onTransitionEnd: handleTransitionEnd, children: jsx("div", { onClick: (e) => e.stopPropagation(), children: children }) }));
};

export { Overlay };
